<script setup lang="ts">
import{computed,ref,watch}from"vue";import{ElMessage}from"element-plus";import{dashboard}from"../api";import AppShell from"../components/AppShell.vue";import AsyncPanel from"../components/AsyncPanel.vue";import{useAsyncData}from"../composables/useAsyncData";import{useFiltersStore}from"../stores/filters";import{usePrefsStore}from"../stores/prefs";
const filters=useFiltersStore(),prefs=usePrefsStore();const month=ref(new Date().toISOString().slice(0,7));void prefs.load();const state=useAsyncData(async()=>{await filters.loadInstances();if(!filters.site_id)return;return dashboard.billingChannels({instance_id:filters.site_id,month:month.value})});const currency=computed(()=>prefs.currencySymbol||"$");const money=(v:string)=>`${currency.value}${Number(v||0).toFixed(4)}`;async function saveDiscount(row:any,value:string){const n=Number(value);if(!Number.isFinite(n)||n<0||n>1){ElMessage.warning("折扣必须在 0 到 1 之间");return}await dashboard.saveBillingChannelDiscount({instance_id:filters.site_id,channel_id:row.channel_id,discount:String(n)});row.discount=String(n);row.discounted_amount=(Number(row.amount)*n).toFixed(6);ElMessage.success("渠道折扣已保存")};function dates(){const start=`${month.value}-01`;const d=new Date(`${start}T00:00:00`);const end=new Date(d.getFullYear(),d.getMonth()+1,0);return{start,end:`${end.getFullYear()}-${String(end.getMonth()+1).padStart(2,"0")}-${String(end.getDate()).padStart(2,"0")}`}}function anomalyURL(row:any){const d=dates();return`/api/dashboard/billing/anomalies?instance_id=${encodeURIComponent(filters.site_id)}&channel_id=${row.channel_id}&from=${d.start}&to=${d.end}&format=csv&limit=5000`}watch([month,()=>filters.site_id],()=>state.reload());void state.reload();
</script>
<template><AppShell title="渠道账单"><template #tools><el-date-picker v-model="month" type="month" value-format="YYYY-MM" format="YYYY-MM" :clearable="false"/></template><AsyncPanel :loading="state.loading.value" :error="state.error.value" :empty="!state.data.value?.items?.length" @retry="state.reload"><el-table :data="state.data.value?.items||[]"><el-table-column prop="channel_name" label="渠道" min-width="160"><template #default="s"><b>{{s.row.channel_name||`渠道 ${s.row.channel_id}`}}</b><small class="sub">ID {{s.row.channel_id}}</small></template></el-table-column><el-table-column prop="request_count" label="请求数"/><el-table-column prop="prompt_tokens" label="输入 Token" min-width="120"/><el-table-column prop="completion_tokens" label="输出 Token" min-width="120"/><el-table-column prop="cache_tokens" label="缓存 Token" min-width="120"/><el-table-column label="账单原价"><template #default="s">{{money(s.row.amount)}}</template></el-table-column><el-table-column label="折扣" width="130"><template #default="s"><el-input-number :model-value="Number(s.row.discount)" :min="0" :max="1" :step="0.01" :precision="2" size="small" @change="saveDiscount(s.row,String($event))"/></template></el-table-column><el-table-column label="折扣总金额"><template #default="s"><b>{{money(s.row.discounted_amount)}}</b></template></el-table-column><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" tag="a" :href="anomalyURL(s.row)">异常订单</el-button></template></el-table-column></el-table></AsyncPanel></AppShell></template>
<style scoped>.sub{display:block;color:var(--el-text-color-secondary);margin-top:3px}</style>
